def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # Near the very end: opportunistically defect against highly cooperative opponents.
    if n >= 95:
        if opp_c >= n - 3:
            return 'D'
        if opp_c * 5 >= n * 4:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'C'

    # Detect truly relentless defectors.
    if n >= 10 and opp_d >= n - 1:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Count short recent windows.
    w5 = min(5, n)
    recent5 = opp[-w5:]
    rec5_c = sum(1 for a in recent5 if a == 'C')

    w10 = min(10, n)
    recent10 = opp[-w10:]
    rec10_c = sum(1 for a in recent10 if a == 'C')

    # If opponent just defected, retaliate, but forgive after a limited streak.
    if last_opp == 'D':
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 4:
            # Try to break out of mutual defection occasionally.
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if streak == 1:
            # Strong immediate retaliation.
            if last_me == 'C':
                return 'D'
            return 'D'
        # streak 2-3: mostly defect but sometimes test cooperation.
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If cooperative overall, mostly cooperate but exploit sparingly.
    if n >= 15:
        if opp_d == 0:
            # Perfect cooperator: keep it going, probe rarely.
            if rng.random() < 0.03:
                return 'D'
            return 'C'
        if w10 >= 10 and rec10_c >= 9:
            if rng.random() < 0.1:
                return 'D'
            return 'C'

    # If opponent is mostly defecting, defend.
    if n >= 6 and rec5_c <= 1:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Tit-for-tat with forgiveness and small probing.
    if last_opp == 'C':
        if n >= 5 and rec5_c == 5 and opp_d > 0:
            if rng.random() < 0.06:
                return 'D'
        return 'C'

    return 'C'
